function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var d=+q('an-m').value,t=+q('an-t').value;var m=q('an-msg');
if(d===0){m.innerHTML='✅ Aucun inhibiteur de PDE5 — trinitrine utilisable. Rappel : <b>s\'asseoir</b> avant la prise, et appeler le 15 si la douleur persiste après 2 prises espacées de 5 min';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}
else if(t<d){m.innerHTML='⛔ <b>CONTRE-INDICATION ABSOLUE</b> — dérivés nitrés INTERDITS pendant encore '+(d-t)+' h (risque de collapsus par accumulation de GMPc)';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else{m.innerHTML='✅ Délai de sécurité écoulé ('+d+' h) — dérivés nitrés à nouveau utilisables';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}}
bind(['an-m','an-t'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var w={'fa-c':1,'fa-h':1,'fa-a2':2,'fa-d':1,'fa-s2':2,'fa-v':1,'fa-a':1,'fa-sc':1},t=0;
for(var k in w){if(q(k).checked)t+=w[k];}
q('fa-sc2').textContent=t;
var f=q('fa-sc').checked;var m=q('fa-msg');
var seuil=f?3:2;
if(t>=seuil){m.innerHTML='✅ <b>ANTICOAGULATION RECOMMANDÉE</b> — AOD en 1re intention dans la FA non valvulaire (AVK obligatoires si valve mécanique ou RM rhumatismal)';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}
else if(t===seuil-1&&t>0){m.innerHTML='⚖️ Anticoagulation À DISCUTER au cas par cas';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else{m.innerHTML='Pas d\'anticoagulation indiquée sur ce score. Rappel : le score HAS-BLED n\'est <b>PAS</b> une contre-indication, il identifie les facteurs de risque hémorragique MODIFIABLES';m.style.background='rgba(59,130,246,.15)';m.style.color='#60a5fa';}}
bind(['fa-c','fa-h','fa-a2','fa-d','fa-s2','fa-v','fa-a','fa-sc'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var l=+q('ld-l').value,c=+q('ld-r').value;
q('ld-c').textContent=c.toFixed(2);
var b=Math.max(0,(1-c/l)*100);q('ld-b').textContent=b.toFixed(0);
var m=q('ld-msg');
if(b<=0){m.innerHTML='✅ Cible ATTEINTE — poursuivre le traitement et les mesures hygiéno-diététiques';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}
else if(b<=30){m.innerHTML='Statine d\'intensité modérée suffisante (≈ 30 % de baisse)';m.style.background='rgba(59,130,246,.15)';m.style.color='#60a5fa';}
else if(b<=50){m.innerHTML='⚠️ <b>Statine de FORTE intensité</b> (atorvastatine 40-80 mg, rosuvastatine 20-40 mg)';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else if(b<=65){m.innerHTML='⚠️ Statine forte intensité + <b>ÉZÉTIMIBE</b> (+15 à 20 %). Rappel « règle du 6 » : doubler la statine n\'apporte que ≈ 6 %';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else{m.innerHTML='🚨 Trithérapie nécessaire : statine + ézétimibe + <b>inhibiteur de PCSK9</b>. Évoquer une hypercholestérolémie familiale';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}}
bind(['ld-l','ld-r'],u);

function q(i){return container.querySelector('#'+i);}function bind(ids,f){ids.forEach(function(i){var e=q(i);e.addEventListener('input',f);e.addEventListener('change',f);});f();}function u(){var d=+q('rc-d').value;
var st=d>=90?'1':d>=60?'2':d>=45?'3A':d>=30?'3B':d>=15?'4':'5';
q('rc-st').textContent=st;
var m=q('rc-msg');
if(d<15){m.innerHTML='🚨 Stade 5 — préparation de la SUPPLÉANCE (dialyse ou greffe), abord vasculaire, inscription en liste';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(d<30){m.innerHTML='🚨 Stade 4 — adaptation posologique systématique, information et préparation à la suppléance';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else if(d<60){m.innerHTML='⚠️ Stade 3 — <b>adaptation posologique requise</b>, dépistage des complications (anémie, troubles phosphocalciques, acidose)';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}
else{m.innerHTML='Stades 1-2 — néphroprotection : contrôle tensionnel, IEC/ARA2 si albuminurie, gliflozine, éviction des néphrotoxiques';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}
var L=[];
L.push((d<30?'⛔':d<45?'⚠️':'✅')+' <b>Metformine</b> : '+(d<30?'CONTRE-INDIQUÉE':d<45?'demi-dose':'dose pleine')+' — suspendre si déshydratation ou produit de contraste');
L.push((d<15?'⛔':d<30?'⚠️':'✅')+' <b>AOD</b> : '+(d<15?'contre-indiqués':d<30?'réduction de dose selon la molécule':'dose adaptée au poids et à l\'âge'));
L.push((d<30?'⛔':'⚠️')+' <b>AINS</b> : à proscrire — « triple whammy » avec IEC/ARA2 + diurétique');
L.push('⚠️ <b>Aminosides / vancomycine</b> : espacer les doses, suivi thérapeutique pharmacologique');
L.push((d<30?'⚠️':'✅')+' <b>Morphine</b> : accumulation du métabolite actif M6G — préférer une autre molécule si DFG < 30');
q('rc-list').innerHTML=L.join('<br>');}
bind(['rc-d'],u);

function q(i){return container.querySelector('#'+i);}
var ids=['e1','e2','e3','e4','e5'];
function u(){var n=ids.filter(function(i){return q(i).checked;}).length;
q('e-n').textContent=n;var m=q('e-msg');
if(n===5){m.innerHTML='✅ BEP complet — négociez les objectifs <b>avec</b> le patient en partant de sa dimension PROJECTIVE';m.style.background='rgba(58,176,158,.15)';m.style.color='#3ab09e';}
else if(!q('e5').checked){m.innerHTML='⚠️ La dimension <b>PROJECTIVE manque</b> — la plus souvent oubliée et pourtant le levier de motivation le plus puissant. Sans elle, les objectifs seront ceux du soignant.';m.style.background='rgba(239,68,68,.15)';m.style.color='#ef4444';}
else{m.innerHTML='Bilan partiel ('+n+'/5) — un BEP incomplet produit des objectifs hors sujet';m.style.background='rgba(251,191,36,.15)';m.style.color='#fbbf24';}}
ids.forEach(function(i){q(i).addEventListener('change',u);});u();
